#!/usr/bin/env python3
"""Embed and package existing design assets byte-for-byte; never edits images or app code."""
from pathlib import Path
import base64, hashlib, html, io, json, re, struct, tarfile

ROOT = Path(__file__).resolve().parents[4]
ADAPTIVE = ROOT / 'design-reference/adaptive'
HANDOFF = ROOT / 'docs/handoff/adaptive-v3'
STANDALONE = ROOT / 'JOVRA-Adaptive-Watch-v3.html'
ARCHIVE = ROOT / 'JOVRA-Claude-Adaptive-Watch-v3.tar.gz'
E = lambda x: html.escape(str(x), quote=True)

def digest(data):
    return hashlib.sha256(data).hexdigest()

def rel(path):
    return path.relative_to(ROOT).as_posix()

def data_uri(path):
    return 'data:image/png;base64,' + base64.b64encode(path.read_bytes()).decode()

def path_for(row):
    if row['id'] <= 20:
        return ROOT / 'design-reference/screens' / (f"{row['id']:02d}-{row['slug']}.png")
    if row['id'] <= 40:
        return ROOT / 'design-reference/studio/screens' / (f"{row['id']}-{row['slug']}.png")
    return ADAPTIVE / 'screens' / (f"{row['id']}-{row['slug']}.png")

rows = json.loads((ADAPTIVE / 'brief/screen-specs.json').read_text())
assert len(rows) == 32 and [r['id'] for r in rows] == list(range(41, 73))
old_raw = json.loads((ROOT / 'design-reference/brief/screens.json').read_text())
old = [{'id':r['n'], 'slug':r['id'], 'title':r['title'], 'format':'phone', 'visual':r['layout']} for r in old_raw]
studio = json.loads((ROOT / 'design-reference/studio/brief/screens.json').read_text())
for r in old + studio:
    r['format'] = 'tablet' if r.get('format') == 'landscape' else 'phone'
for r in rows:
    assert path_for(r).is_file(), r
    raw = path_for(r).read_bytes()
    assert raw[:8] == b'\x89PNG\r\n\x1a\n'
    r['width'], r['height'] = struct.unpack('>II', raw[16:24])
    r['sha256'] = digest(raw)
    r['bytes'] = len(raw)
    r['path'] = rel(path_for(r))
(ADAPTIVE / 'asset-manifest.json').write_text(json.dumps({'generatedTargets': True, 'nativeEmulatorCaptures': False, 'assets': rows}, indent=2) + '\n')

docs = {}
for folder in (ADAPTIVE / 'brief', HANDOFF):
    for path in sorted(folder.rglob('*')):
        if path.is_file() and path.suffix in {'.md', '.json', '.py'} and '__pycache__' not in path.parts:
            if path.name in {'package-manifest.json'}: continue
            docs[rel(path)] = path.read_text()
prompt_name = rel(HANDOFF / 'CLAUDE-ADAPTIVE-WATCH-PROMPT.md')
start_name = rel(HANDOFF / 'START-HERE.md')
skill_names = [rel(p) for p in sorted((HANDOFF / 'skills').glob('*/SKILL.md'))]
assert len(skill_names) == 2

CSS = '''
:root{--ivory:#f4f1e8;--forest:#092a25;--panel:#123c33;--lime:#d7f56a;--clay:#c47752;--muted:#bac9bc;--line:#416058}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--forest);color:var(--ivory);font:16px/1.6 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--lime)}button,a.action{font:inherit;cursor:pointer;min-height:44px;border:1px solid var(--line);border-radius:30px;padding:10px 18px;background:var(--panel);color:var(--ivory);text-decoration:none;display:inline-flex;align-items:center;justify-content:center}button:hover,a.action:hover{border-color:var(--lime)}button[aria-pressed=true],.primary{background:var(--lime)!important;color:var(--forest)!important}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--lime);outline-offset:4px}header{max-width:1480px;margin:auto;padding:24px 4vw;display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap}.brand{font-size:24px;font-weight:800;letter-spacing:.12em;color:var(--ivory);text-decoration:none}.brand b{color:var(--lime)}.eyebrow{color:var(--lime);letter-spacing:.15em;text-transform:uppercase;font-size:12px;font-weight:700}.hero{max-width:1480px;margin:auto;display:grid;grid-template-columns:1.1fr .9fr;gap:4vw;padding:48px 4vw 56px;align-items:center}.hero h1{font-size:clamp(42px,5.2vw,80px);line-height:1.06;letter-spacing:-.045em;margin:16px 0 22px;max-width:850px}.hero h1 em{color:var(--lime);font-style:normal}.lead{font-size:20px;color:var(--muted);max-width:680px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.hero-art{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:center}.hero-art img{display:block;width:100%;border-radius:24px}.hero-art figure{margin:0}.hero-art figcaption{font-size:13px;color:var(--muted);margin:8px 0}.hero-art .fold{grid-column:1/-1}.hero-art .fold img{max-height:290px;object-fit:contain;background:var(--ivory)}.numbers{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);max-width:1360px;margin:0 auto}.numbers div{padding:22px}.numbers strong{font-size:36px;color:var(--lime);display:block;line-height:1.2}.numbers span{font-size:13px;color:var(--muted)}main{max-width:1480px;margin:auto;padding:48px 4vw}h2{font-size:clamp(28px,3vw,44px);line-height:1.2;letter-spacing:-.03em}h3{line-height:1.25}p{overflow-wrap:anywhere}.notice{font-size:14px;color:var(--muted);max-width:900px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0 16px}.search{width:100%;max-width:400px;background:#06211d;color:var(--ivory);border:1px solid var(--line);border-radius:12px;padding:12px 16px;font:inherit;margin:10px 0 18px}.count{color:var(--muted);font-size:14px;margin-bottom:22px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px}.card{background:var(--panel);border:1px solid var(--line);border-radius:20px;overflow:hidden;min-width:0}.card[hidden]{display:none}.image-button{display:block;width:100%;padding:0;border:0;border-radius:0;background:var(--ivory);min-height:0}.image-button img{display:block;width:100%;height:360px;object-fit:contain}.card.fold,.card.tablet,.card.iosfold{grid-column:span 2}.card.fold .image-button img,.card.tablet .image-button img,.card.iosfold .image-button img{height:360px}.card.watchos .image-button img,.card.wearos .image-button img{height:280px}.card-body{padding:18px}.tag{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--lime)}.card h3{font-size:19px;margin:8px 0}.card p{font-size:13px;color:var(--muted);margin:8px 0}.card-body a{font-size:13px}section{margin:50px 0}.workflow{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.workflow article{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:24px}.workflow h3{font-size:23px;margin-top:8px}.workflow p{color:var(--muted)}details.doc{border:1px solid var(--line);border-radius:16px;background:var(--panel);padding:18px;margin:12px 0}summary{cursor:pointer;font-weight:650;min-height:44px;display:list-item;overflow-wrap:anywhere}.doc pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#061f1b;padding:20px;border-radius:12px;max-height:65vh;overflow:auto;font:13px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace;color:var(--ivory)}.doc-list{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.doc-list a{border:1px solid var(--line);padding:12px;border-radius:10px;font-size:13px;overflow-wrap:anywhere}.status{min-height:24px;color:var(--lime);font-size:14px}footer{border-top:1px solid var(--line);padding:30px 4vw;color:var(--muted);font-size:13px}dialog{background:var(--forest);color:var(--ivory);border:1px solid var(--line);border-radius:18px;max-width:95vw;width:1100px;max-height:95vh;padding:18px}dialog::backdrop{background:#000b}.modal-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.modal-head h2{font-size:20px}#modal-image{display:block;max-width:100%;max-height:70vh;object-fit:contain;margin:12px auto}.modal-controls{display:flex;gap:10px;justify-content:center}.empty{color:var(--muted)}@media(max-width:1100px){.grid{grid-template-columns:repeat(3,1fr)}.hero{grid-template-columns:1fr}.hero-art{max-width:680px}.workflow{grid-template-columns:1fr 1fr}}@media(max-width:760px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.hero{padding-top:24px}.hero h1{font-size:46px}.hero-art{gap:10px}.numbers{grid-template-columns:repeat(2,1fr)}.numbers div{padding:18px}.image-button img{height:300px}.workflow{grid-template-columns:1fr}.doc-list{grid-template-columns:1fr}}@media(max-width:480px){header{padding:18px}.hero,main{padding-left:18px;padding-right:18px}.hero h1{font-size:42px}.lead{font-size:17px}.grid{grid-template-columns:1fr}.card.fold,.card.tablet,.card.iosfold{grid-column:auto}.image-button img{height:420px}.card.fold .image-button img,.card.tablet .image-button img,.card.iosfold .image-button img{height:320px}.card.watchos .image-button img,.card.wearos .image-button img{height:350px}.toolbar button{padding:10px 14px}.hero-art .fold img{max-height:220px}.doc pre{padding:12px;font-size:12px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{header,.toolbar,.search,dialog,.actions{display:none}.grid{grid-template-columns:repeat(3,1fr)}.card{break-inside:avoid}body{background:white;color:black}.card-body p{color:#333}}
'''

JS = '''
const docs=JSON.parse(document.getElementById('embedded-documents').textContent);let filter='android';const search=document.getElementById('search');const cards=[...document.querySelectorAll('.card')];const modal=document.getElementById('viewer');let activeCard=null;
function included(c){let id=Number(c.dataset.id),f=c.dataset.format;return filter==='all'||filter==='new'&&id>=41||filter==='android'&&id>=41&&id<=60||filter==='watches'&&id>=61&&id<=70||filter==='fold'&&['fold','tablet','iosfold'].includes(f)&&id>=41||filter==='watchos'&&f==='watchos'||filter==='wearos'&&f==='wearos'||filter==='iosfold'&&f==='iosfold'||filter==='prior'&&id<=40;}
function update(){let n=0;const q=search.value.trim().toLowerCase();cards.forEach(c=>{c.hidden=!(included(c)&&c.textContent.toLowerCase().includes(q));if(!c.hidden)n++;});document.getElementById('count').textContent=n+' reference views shown';document.getElementById('empty').hidden=n!==0;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;update();}));search.addEventListener('input',update);
function show(c){activeCard=c;document.getElementById('modal-title').textContent=c.querySelector('h3').textContent;const img=c.querySelector('img');document.getElementById('modal-image').src=img.src;document.getElementById('modal-image').alt=img.alt;document.getElementById('modal-download').href=img.src;document.getElementById('modal-download').download=c.dataset.filename;if(!modal.open)modal.showModal();}
document.querySelectorAll('.image-button').forEach(b=>b.addEventListener('click',()=>show(b.closest('.card'))));document.getElementById('close-viewer').addEventListener('click',()=>modal.close());function next(step){let visible=cards.filter(c=>!c.hidden);if(!visible.length)return;show(visible[(visible.indexOf(activeCard)+step+visible.length)%visible.length]);}document.getElementById('prev').addEventListener('click',()=>next(-1));document.getElementById('next').addEventListener('click',()=>next(1));modal.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')next(-1);if(e.key==='ArrowRight')next(1);});
document.querySelectorAll('[data-image-download]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const c=a.closest('.card');const link=document.createElement('a');link.href=c.querySelector('img').src;link.download=c.dataset.filename;link.click();}));
document.querySelectorAll('[data-download]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();let key=a.dataset.download;if(!(key in docs))return;const blob=new Blob([docs[key]],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=key.split('/').pop();link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('download-status').textContent='Prepared '+link.download;}));document.getElementById('copy-prompt').addEventListener('click',async()=>{const text=docs[PROMPT_NAME];try{await navigator.clipboard.writeText(text);document.getElementById('download-status').textContent='Claude continuation prompt copied.';}catch{document.getElementById('download-status').textContent='Clipboard unavailable. Use Download Claude prompt or select its text below.';}});update();
'''.replace('PROMPT_NAME', json.dumps(prompt_name))

def page(embedded):
    collection = rows if embedded else old + studio + rows
    def image(row):
        return data_uri(path_for(row)) if embedded else ('screens/' if row['id'] >=41 else '../studio/screens/' if row['id']>=21 else '../screens/') + path_for(row).name
    def detail(name, title, opened=False):
        return '<details class="doc"'+(' open' if opened else '')+'><summary>'+E(title)+'</summary><a class="action" href="#documents" data-download="'+E(name)+'">Download this file</a><pre>'+E(docs[name])+'</pre></details>'
    def card(r):
        platform = 'Android' if 41<=r['id']<=60 else 'watchOS' if 61<=r['id']<=65 else 'Wear OS' if 66<=r['id']<=70 else 'iOS adaptive' if r['id']>=71 else 'Prior collection'
        description = r.get('visual', r.get('description','Generated reference target'))
        return '<article class="card '+E(r['format'])+'" data-id="'+str(r['id'])+'" data-format="'+E(r['format'])+'" data-filename="'+E(path_for(r).name)+'"><button class="image-button" aria-label="Open reference '+str(r['id'])+' '+E(r['title'])+'"><img loading="lazy" src="'+image(r)+'" alt="'+E(platform+' '+r['title']+' generated reference')+'"></button><div class="card-body"><span class="tag">'+E(platform)+' / '+E(r['format'])+' / Sample</span><h3>'+str(r['id'])+' · '+E(r['title'])+'</h3><p>'+E(description)+'</p><a href="#collection" data-image-download download="'+E(path_for(r).name)+'">Download PNG →</a></div></article>'
    hero = '<figure><img src="'+image(rows[20])+'" alt="Apple Watch camera health study"><figcaption>watchOS · camera health</figcaption></figure><figure><img src="'+image(rows[25])+'" alt="Wear OS camera health study"><figcaption>Wear OS · round display</figcaption></figure><figure class="fold"><img src="'+image(rows[15])+'" alt="Foldable video editor with separated playback and timeline"><figcaption>Android · expanded edit workspace</figcaption></figure>'
    filters = [('android','Android · 20'),('watches','Watches · 10'),('fold','Expanded · 6'),('watchos','Apple Watch · 5'),('wearos','Galaxy Watch · 5'),('iosfold','iOS fold study · 2'),('new','All new · 32')]
    if not embedded: filters += [('prior','Prior · 40'),('all','Full collection · 72')]
    toolbar=''.join('<button data-filter="'+key+'" aria-pressed="false">'+label+'</button>' for key,label in filters)
    extra='This self-contained file includes all 32 new views and the full addendum text. The prior 40 views and six production editing skills remain in the v2 engine handoff.' if embedded else 'This workspace gallery combines all 72 views. Its prior 40 assets come from the existing v2 handoff; the downloadable v3 addendum includes the 32 new views.'
    briefs=['session-connectivity.md','platform-and-device-plan.md','acceptance-matrix.md','implementation-states.json','watch-snapshot.sample.json']
    brief_details=''.join(detail('design-reference/adaptive/brief/'+name,name) for name in briefs)
    document_list=''.join('<a href="#documents" data-download="'+E(name)+'">'+E(name)+'</a>' for name in docs)
    safe_docs=json.dumps(docs,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JOVRA — Android, foldables and watches · v3</title><style>'+CSS+'</style></head><body><header><a class="brand" href="#top"><b>JV</b> JOVRA</a><a class="action" href="#claude">Claude continuation</a></header><div id="top" class="hero"><div><span class="eyebrow">Studio / native expansion / v3</span><h1>One court.<br>More perspectives.<br><em>Every screen.</em></h1><p class="lead">Android phone and foldable workspaces. Lessons that stay with you. Camera and score updates at a glance on both watches.</p><div class="actions"><a class="action primary" href="#collection">Explore the references</a><a class="action" href="#claude">Use the next Claude prompt</a></div><p class="notice">Generated design targets · sample data · native builds and physical capture unverified. '+extra+'</p></div><div class="hero-art">'+hero+'</div></div><div class="numbers"><div><strong>20</strong><span>Android equivalents</span></div><div><strong>10</strong><span>Native watch views</span></div><div><strong>2</strong><span>iOS foldable studies</span></div><div><strong>72</strong><span>References overall</span></div></div><main><section id="collection"><span class="eyebrow">The reference collection</span><h2>Native details. A shared identity.</h2><p class="notice">Select a family, search a task, or open a reference at full size. Android layouts target compact phones and expanded Pixel Fold/tablet shapes; exact branded emulator availability must be checked during implementation.</p><div class="toolbar">'+toolbar+'</div><label for="search">Find a screen</label><br><input id="search" class="search" type="search" placeholder="Camera, score, lesson, fold…"><div id="count" class="count" role="status" aria-live="polite"></div><div class="grid">'+''.join(card(r) for r in collection)+'</div><p id="empty" class="empty" hidden>No matching references. Try another family or search.</p></section><section><span class="eyebrow">The experience</span><h2>Capture together. Keep every original.</h2><div class="workflow"><article><span class="eyebrow">01 / Room</span><h3>Scan, consent, record.</h3><p>One session invite connects the camera phones. Every phone keeps its own media. Joining a room does not synchronize frames or grant publishing permission.</p></article><article><span class="eyebrow">02 / Companion</span><h3>Useful in a glance.</h3><p>Your paired phone forwards camera health, score and accepted markers to your watch. Stale status stays visible; a lost connection may leave cameras recording.</p></article><article><span class="eyebrow">03 / Story</span><h3>Review into a film.</h3><p>Use the existing five story styles and production skills. Extra angles feed reviewed alignment and cuts, then a private downloadable film and lesson record.</p></article></div><p class="notice">Serve speed is a later source-linked phone capability. Uncertain bounces start as review markers. Camera count alone cannot establish accurate automatic line calls.</p></section><section id="claude"><span class="eyebrow">Hand off the next direction</span><h2>Keep Studio moving.</h2><p class="notice">Give Claude this addendum while its existing Studio work continues. Preserve the installed six editing skills, current ticket and native architecture. The two new portable skills cover adaptive native UI and the watch/session companion.</p><div class="actions"><button id="copy-prompt" class="primary">Copy Claude prompt</button><a class="action" href="#documents" data-download="'+E(prompt_name)+'">Download Claude prompt</a><a class="action" href="#documents" data-download="'+E(start_name)+'">Download START-HERE</a></div><p class="status" id="download-status" role="status" aria-live="polite"></p>'+detail(prompt_name,'Claude continuation prompt',True)+'</section><section id="skills"><h2>Two portable implementation skills.</h2>'+''.join(detail(name,Path(name).parent.name) for name in skill_names)+'</section><section id="briefs"><h2>Pairing, freshness and evidence gates.</h2><p class="notice">Proposed contracts with executable sample checks. They are not an implemented session service or a substitute for native and real-device tests.</p>'+brief_details+'</section><section id="documents"><h2>All addendum source files.</h2><div class="doc-list">'+document_list+'</div></section></main><footer>JOVRA · native/adaptive/watch addendum · 2026-10-07 · All status, QR, photography and metrics are illustrative. Runtime, transport, hardware and cloud activation remain separately verified gates.</footer><dialog id="viewer" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">Reference</h2><button id="close-viewer" aria-label="Close reference">Close ×</button></div><img id="modal-image" alt=""><div class="modal-controls"><button id="prev" aria-label="Previous reference">←</button><a id="modal-download" class="action" download>Download PNG</a><button id="next" aria-label="Next reference">→</button></div></dialog><script id="embedded-documents" type="application/json">'+safe_docs+'</script><script>'+JS+'</script></body></html>'

(ADAPTIVE / 'index.html').write_text(page(False))
STANDALONE.write_text(page(True))
files={}
for folder in (ADAPTIVE,HANDOFF):
    for path in sorted(folder.rglob('*')):
        if not path.is_file() or '__pycache__' in path.parts or path.name in {'.DS_Store','package-manifest.json'}: continue
        files[rel(path)]=path.read_bytes()
files[STANDALONE.name]=STANDALONE.read_bytes()
manifest={'version':3,'newReferences':32,'overallReferences':72,'newPortableSkills':2,'previousV2RequiredForPrior40GalleryAssets':True,'files':[{'path':name,'bytes':len(raw),'sha256':digest(raw)} for name,raw in sorted(files.items())]}
(ADAPTIVE/'brief/package-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
files[rel(ADAPTIVE/'brief/package-manifest.json')]=(ADAPTIVE/'brief/package-manifest.json').read_bytes()
with tarfile.open(ARCHIVE,'w:gz') as archive:
    for name,raw in sorted(files.items()):
        info=tarfile.TarInfo('JOVRA-Adaptive-Watch-v3/'+name);info.size=len(raw);info.mode=0o644;info.mtime=0
        archive.addfile(info,io.BytesIO(raw))
archive_hash=digest(ARCHIVE.read_bytes())
(ROOT/(ARCHIVE.name+'.sha256')).write_text(archive_hash+'  '+ARCHIVE.name+'\n')
print(json.dumps({'newScreens':len(rows),'galleryTotal':len(old+studio+rows),'documentsEmbedded':len(docs),'archiveBytes':ARCHIVE.stat().st_size,'archiveSha256':archive_hash,'standaloneBytes':STANDALONE.stat().st_size},indent=2))
